@layer cojeev-states {
/* Content-driven narrow layout and morph-preview paint need the component boundary. */
[data-slot="adjuster"] [data-part="body"][hidden] { display: none; }
[data-slot="adjuster"] [data-slot="adjuster-preview"] { --mfill: var(--v-pink); background: var(--v-pink); padding: 12px 24px; }
[data-slot="adjuster"] [data-slot="adjuster-preview"]:has(>svg.v-morph) { background: transparent; }
[data-slot="adjuster"] [data-part="error"] { color: var(--v-danger-ink); }
.v-motion-controls { display:grid; gap:24px; min-width:0; color:var(--v-text); }
.v-motion-controls__row { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:16px; }
.v-motion-controls__row > div { display:grid; gap:4px; min-width:0; }
.v-motion-controls__section { display:grid; gap:12px; }
.v-motion-controls__characters { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; }
.v-motion-controls__characters > button { min-width:0; min-height:44px; padding-inline:8px; }
.v-motion-controls__description { min-height:3em; }
.v-motion-controls__preview { display:grid; gap:16px; padding:20px 16px; border-radius:var(--r-card-sm); background:var(--v-beige); }
.v-motion-controls__preview [data-slot="tabs-list"] { width:100%; gap:4px; }
.v-motion-controls__preview [data-slot="tabs-trigger"] { flex:1; min-width:0; padding-inline:8px; }
.v-motion-controls__preview [data-slot="tabs-content"] { min-height:82px; padding-top:20px; }
.v-motion-controls [data-slot="slider"] { margin-block:8px; }
@container (max-width: 480px) {
 [data-slot="adjuster"] [data-part="grid"] { grid-template-columns: minmax(0, 1fr); }
 [data-slot="adjuster"] [data-part="body"] { padding: 0 12px 12px; }
 [data-slot="adjuster"] fieldset { padding: 12px; }
}

}
